# Asignar IDs únicos bmw_001, bmw_002, etc. y campos compatibles
catalog = []
for idx, m in enumerate(raw_modelos, start=1):
    m_copy = dict(m)
    m_copy["id"] = f"bmw_{idx:03d}"
    m_copy["nombre"] = m["modelo"]
    catalog.append(m_copy)

datos = {
    "version": 1,
    "modelos": catalog
}

with open("datos/modelos_bmw.json", "w", encoding="utf-8") as f:
    json.dump(datos, f, ensure_ascii=False, indent=2)

print(f"Creado catálogo con {len(catalog)} modelos de BMW en datos/modelos_bmw.json")
